import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import "./theme.css";

function Planner() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);
  const [courses, setCourses] = useState([]);
  const [form, setForm] = useState({
    course_id: "",
    study_date: "",
    topic: ""
  });

  const loadData = async () => {
    const p = await axios.get(`http://127.0.0.1:8000/planner/${userId}`);
    setPlans(p.data.plans || []);

    const c = await axios.get("http://127.0.0.1:8000/courses");
    setCourses(c.data.courses || []);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAdd = async (e) => {
    e.preventDefault();

    await axios.post("http://127.0.0.1:8000/create-plan", {
      user_id: parseInt(userId),
      course_id: parseInt(form.course_id),
      study_date: form.study_date,
      topic: form.topic
    });

    setForm({ course_id: "", study_date: "", topic: "" });
    loadData();
  };

  return (
    <AppShell title="Planner" subtitle="Create and manage your daily study plan">
      <div className="page-grid-2">

        <Panel title="Create Plan">
          <form onSubmit={handleAdd}>
            <select
              className="select"
              value={form.course_id}
              onChange={(e) =>
                setForm({ ...form, course_id: e.target.value })
              }
            >
              <option value="">Select Course</option>
              {courses.map((c) => (
                <option key={c.id} value={c.id}>{c.title}</option>
              ))}
            </select>

            <input
              type="date"
              className="input"
              value={form.study_date}
              onChange={(e) =>
                setForm({ ...form, study_date: e.target.value })
              }
            />

            <input
              className="input"
              placeholder="Topic"
              value={form.topic}
              onChange={(e) =>
                setForm({ ...form, topic: e.target.value })
              }
            />

            <button className="btn btn-primary">Add Plan</button>
          </form>
        </Panel>

        <Panel title="Your Plans">
          {plans.map((p) => {
            const isExpired = new Date(p.study_date) < new Date();

            return (
              <div className="list-card" key={p.id}>
                <h4>{p.topic}</h4>
                <div className="muted">Date: {p.study_date}</div>

                <div style={{ marginTop: "10px" }}>
                  {p.status === "Completed" && (
                    <span className="badge badge-green">Completed</span>
                  )}
                  {p.status === "Pending" && !isExpired && (
                    <span className="badge badge-purple">Pending</span>
                  )}
                  {isExpired && (
                    <span className="badge badge-orange">Expired</span>
                  )}
                </div>

                <div className="btn-row" style={{ marginTop: "10px" }}>
                  {!isExpired && p.status !== "Completed" && (
                    <button className="btn btn-primary">
                      Mark Done
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </Panel>

      </div>
    </AppShell>
  );
}

export default Planner;
